def transform(grid):
    from collections import Counter

    # Determine Background Color (most frequent)
    counts = Counter()
    for row in grid:
        counts.update(row)

    if not counts:
        return grid

    bg_color = max(counts, key=counts.get)

    # Store original rows to compute references without using modified rows
    original_rows = [list(row) for row in grid]
    new_grid = []

    def get_fg_count(row, bg):
        return sum(1 for x in row if x != bg)

    for i in range(len(grid)):
        row_i = original_rows[i]

        best_ref_idx = -1
        max_score = -1
        max_fg_ref = -1

        # Search for the best reference row
        for j in range(len(grid)):
            if i == j:
                continue

            row_j = original_rows[j]

            # Calculate Score: Number of matching FG pixels between row_i and row_j
            # Only counts if row_i has FG and row_j has the same FG.
            score = 0
            for c in range(len(row_i)):
                val_i = row_i[c]
                val_j = row_j[c]
                if val_i != bg_color:
                    if val_i == val_j:
                        score += 1

            fg_count_j = get_fg_count(row_j, bg_color)

            # Select best reference
            if score > max_score:
                max_score = score
                best_ref_idx = j
                max_fg_ref = fg_count_j
            elif score == max_score:
                # Tie-breaker: Prefer row with more FG pixels (more "complete")
                if fg_count_j > max_fg_ref:
                    best_ref_idx = j
                    max_fg_ref = fg_count_j

        if best_ref_idx != -1:
            ref_row = original_rows[best_ref_idx]
            # Construct new row
            new_row = list(row_i)
            for c in range(len(new_row)):
                val_i = new_row[c]
                val_ref = ref_row[c]
                # If current has BG, and ref has FG -> replace with 1 (repair)
                if val_i == bg_color and val_ref != bg_color:
                    new_row[c] = 1
            new_grid.append(new_row)
        else:
            new_grid.append(row_i)

    return new_grid
